  }
  :root a:hover {
    background-color: inherit;
  }
  :root a[href]:link {
    color: #8839ef;
  }
  :root a[href]:visited {
    color: #825cc1;
  }
  :root a[href].def:link,
  :root a[href].def:visited {
    color: #6c6f85;
  }
  :root a[href].def:hover {
    color: #74778c;
  }
  :root button {
    background-color: #e6e9ef;
    color: #4c4f69;
  }
  :root button:hover {
    background-color: #dce0e8;
  }
  :root .caption,
  :root h1,
  :root h2,
  :root h3,
  :root h4,
  :root h5,
  :root h6,
  :root summary,
  :root .section1,
  :root .section2,
  :root .section3,
  :root .section4,
  :root .section5,
  :root .section6 {
    color: #4c4f69;
    filter: none;
  }
  :root .collapser::before,
  :root .expander::before,
  :root .noexpander::before {
    color: #8839ef;
  }
  :root pre {
    background-color: #e6e9ef;
    border-color: #bcc0cc;
  }
  :root blockquote {
    background-color: #ccd0da;
    border-color: #8839ef;
  }
  :root .src,
  :root .decl,
  :root .declname,
  :root .declbut,
  :root .topdecl,
  :root .arg,
  :root .inline-code {
    background-color: #e6e9ef;
    color: #4c4f69;
  }
  :root .declbut {
    border-color: #9ca0b0 !important;
  }
  :root .declbut a {
    color: #7c7f93 !important;
  }
  :root #page-header,
  :root #package-header {
    background-color: #8839ef;
    color: #bcc0cc;
    border-color: #662bb3;
  }
  :root #page-header .caption,
  :root #package-header .caption,
  :root #page-header a:link,
  :root #page-header a:visited {
    color: #eff1f5 !important;
  }
  :root #module-header .caption,
  :root .modulebar {
    color: #8839ef;
    border-color: #bcc0cc;
  }
  :root #module-header {
    background-color: inherit;
  }
  :root #package-header a:link,
  :root #package-header #page-menu a:link,
  :root #package-header a:visited,
  :root #package-header #page-menu a:visited {
    color: #eff1f5;
  }
  :root #package-header a:hover {
    background-color: transparent;
  }
  :root #package-header ul.links li {
    border-color: #9ca0b0;
  }
  :root #package-header ul.links li:hover {
    background-color: transparent;
  }
  :root ul.links li form input,
  :root ul.links li form button {
    color: #eff1f5;
  }
  :root ul.links li form button {
    background-color: transparent;
  }
  :root .topbar {
    background-color: #8839ef;
  }
  :root .topbar .topbut {
    border-color: #9ca0b0;
  }
  :root .topbar .topbut a {
    background-color: transparent;
    color: #eff1f5;
  }
  :root .topbar .title {
    color: #eff1f5;
  }
  :root .botbar {
    background-color: #dce0e8;
    color: #4c4f69;
  }
  :root #style-menu {
    background-color: #e6e9ef;
  }
  :root #style-menu li,
  :root #style-menu li a {
    color: #4c4f69 !important;
  }
  :root #style-menu li + li {
    border-color: #7c7f93;
  }
  :root a.unpreferred[href]:link,
  :root a.unpreferred[href]:visited {
    color: #df8e1d;
  }
  :root a.deprecated[href]:link,
  :root a.deprecated[href]:visited {
    color: #d20f39;
  }
  :root .versions a.normal[href]:link,
  :root .versions a.normal[href]:visited {
    color: #40a02b;
  }
  :root .embedded-author-content {
    border-color: #8839ef;
